/* ============================================================
   DEFEAT SEQUENCES FROM GEMINI'S PAINTED FRAMES (wekufü bosses)
   Four painted frames per boss: struck, cracking, breaking apart, what is left.
   For the ngen and secret bosses a ngen wakes first: the ground trembles and a deep sound rises
   while a line explains what is happening, then its newen breaks the wekufü.
   The Santiago wardens go straight into their frames. The Yewen keeps its crowd of Santiago people,
   whose calls now move it through its painted frames until the boy is left standing.
   Bosses who are not wekufü (Epunamun, the Millalobo) do not break: their frames show them yielding.
   Epunamun stays standing on screen while the closing lines play; the Millalobo sinks back into the sea.
   With the classic graphics the older defeat animations play instead.
   ============================================================ */
const DSEQ_D={"trelke":[["data:image/png;base64,",30,3],["data:image/png;base64,",36,10],["data:image/png;base64,",32,6],["data:image/png;base64,",35,50]],"witranalwe":[["data:image/png;base64,",-1,3],["data:image/png;base64,",6,34],["data:image/png;base64,",2,19],["data:image/png;base64,",-2,78]],"cherrufe":[["data:image/png;base64,",0,3],["data:image/png;base64,",8,6],["data:image/png;base64,",3,9],["data:image/png;base64,",3,48]],"kaleuche":[["data:image/png;base64,",20,11],["data:image/png;base64,",14,3],["data:image/png;base64,",14,-13],["data:image/png;base64,",20,61]],"walichu":[["data:image/png;base64,",14,3],["data:image/png;base64,",12,20],["data:image/png;base64,",16,14],["data:image/png;base64,",12,57]],"chinifilu":[["data:image/png;base64,",36,3],["data:image/png;base64,",33,16],["data:image/png;base64,",34,19],["data:image/png;base64,",36,50]],"piwuchen":[["data:image/png;base64,",28,3],["data:image/png;base64,",34,9],["data:image/png;base64,",36,15],["data:image/png;base64,",39,70]],"wallipen":[["data:image/png;base64,",24,3],["data:image/png;base64,",24,23],["data:image/png;base64,",22,6],["data:image/png;base64,",30,37]],"trawko":[["data:image/png;base64,",10,3],["data:image/png;base64,",18,26],["data:image/png;base64,",18,18],["data:image/png;base64,",19,57]],"chadikura":[["data:image/png;base64,",10,3],["data:image/png;base64,",12,8],["data:image/png;base64,",5,-7],["data:image/png;base64,",16,61]],"kalku":[["data:image/png;base64,",30,3],["data:image/png;base64,",28,20],["data:image/png;base64,",26,10],["data:image/png;base64,",28,62]],"ngoyngoyun":[["data:image/png;base64,",16,3],["data:image/png;base64,",33,3],["data:image/png;base64,",35,-30],["data:image/png;base64,",34,43]],"ngamlef":[["data:image/png;base64,",31,10],["data:image/png;base64,",31,-2],["data:image/png;base64,",28,-11],["data:image/png;base64,",28,13]],"fillantu":[["data:image/png;base64,",36,-33],["data:image/png;base64,",39,-1],["data:image/png;base64,",39,-1],["data:image/png;base64,",38,-15]],"yewen":[["data:image/png;base64,",18,7],["data:image/png;base64,",18,3],["data:image/png;base64,",36,52],["data:image/png;base64,",41,65]],"epunamun":[["data:image/png;base64,",4,11],["data:image/png;base64,",13,3],["data:image/png;base64,",17,3],["data:image/png;base64,",14,1]],"llufu5":[["data:image/png;base64,",54,3],["data:image/png;base64,",54,3],["data:image/png;base64,",53,-1],["data:image/png;base64,",51,62]]};
const DSEQ={};
(function(){for(const t in DSEQ_D){DSEQ[t]=[];DSEQ_D[t].forEach(([u,dx,dy],k)=>{const im=new Image();im.onload=()=>{DSEQ[t][k]={im,dx,dy}};im.src=u})}})();
const DSQ_NGN={lafken:'Ngen-lafken',mawida:'Ngen-mawida',pewen:'Ngen-pewen',kuruf:'Ngen-kürüf',lelfun:'Ngen-lelfün'};
const DSQ_COL={lafken:'120,220,255',mawida:'120,255,150',pewen:'255,200,110',kuruf:'225,240,255',lelfun:'255,230,120'};
function dseqOK(t){const f=DSEQ[t];return !!(typeof GEM_ON!=='undefined'&&GEM_ON&&GEM_READY&&f&&f[0]&&f[1]&&f[2]&&f[3])}
const DSQ_P=70,DSQ_L=230;   // the ngen's waking, then the four frames and the fade
function dseqStart(e,v,o){const P=v?DSQ_P:0;B.defA={t:0,e,k:e.t,T:P+DSQ_L,D:{seq:1,v,yld:!!(o&&o.yld),keep:!!(o&&o.keep)},P,go:!v};const d=document.getElementById('dlg');if(d)d.style.display='none';active=null}
const _defStart0=defStart;defStart=function(e){if(e.t!=='yewen'&&dseqOK(e.t))return dseqStart(e,null);return _defStart0(e)};
const _defSkip0=defSkip;defSkip=function(){const A=B.defA;if(A&&A.D&&A.D.seq&&!A.go){if(active)active.a();return}return _defSkip0()};
const _drawDef0=drawDefeat;drawDefeat=function(c){const A=B.defA;if(A&&(!A.done||A.D&&A.D.keep)&&A.D&&A.D.seq)return drawSeq(c,A);return _drawDef0(c)};

/* the ngen waking: a deep groan from the earth swelling up, a rumble, then an open fifth like a long breath, and a shimmer */
function ngenWake(){if(!AU.c||AU.muted)return;const c=AU.c,t=c.currentTime;
  const osc=(type,f0,f1,a,peak,hold,rel,v,del)=>{const o=c.createOscillator(),g=c.createGain(),s=t+(del||0);o.type=type;o.frequency.setValueAtTime(f0,s);o.frequency.exponentialRampToValueAtTime(f1,s+a+hold);
    g.gain.setValueAtTime(.0001,s);g.gain.exponentialRampToValueAtTime(v,s+a);g.gain.setValueAtTime(v,s+a+hold);g.gain.exponentialRampToValueAtTime(.0001,s+a+hold+rel);o.connect(g);g.connect(AU.sfx);o.start(s);o.stop(s+a+hold+rel+.05)};
  osc('sine',36,41,1.4,0,.6,1.6,.55);osc('sine',54,61.5,1.4,0,.6,1.6,.3);osc('triangle',27,30.8,1.6,0,.4,1.4,.25);
  if(AU.noise){const s=c.createBufferSource();s.buffer=AU.noise;s.loop=true;const f=c.createBiquadFilter();f.type='lowpass';f.frequency.value=150;const g=c.createGain();
    g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.45,t+1.1);g.gain.exponentialRampToValueAtTime(.0001,t+3);s.connect(f);f.connect(g);g.connect(AU.sfx);s.start(t);s.stop(t+3.1)}
  osc('triangle',110,110,.9,0,.8,1.4,.12,1.3);osc('triangle',165,165,.9,0,.8,1.4,.09,1.45);osc('sine',220,220,.9,0,.6,1.4,.06,1.6);
  [880,1109,1319,1760].forEach((f,i)=>osc('sine',f,f,.05,0,.05,.9,.035,2.2+i*.12))}

function dsqFrame(A,k){return DSEQ[A.k][k]}
function drawSeq(c,A){const e=A.e,D=A.D,P=A.P,ng=e.t==='ngamlef'&&typeof NGK!=='undefined'?NGK:1;
  if(!A.init){A.init=1;dWorld(A);A.f=frame;A.gy=(e._bse||138)+4;const cvs=enemyCanvas(e.t,ET[e.t].bs,0);A.cvs=cvs;A.W=cvs.width;A.H=cvs.height;
    A.left=(e._cx||72)+Math.ceil(A.W/2)-A.W;A.top=e._y!=null?e._y:12;A.col=D.v?(DSQ_COL[D.v]||'120,220,255'):'255,236,190';A.fallY=0;A.fallV=0}
  const n=Math.max(0,Math.min(6,frame-A.f));A.f=frame;
  for(let i=0;i<n&&A.t<A.T;i++){if(P&&A.t>=P-1&&!A.go)break;A.t++;stepSeq(A);dStep(A)}
  const t=A.t,s=t-P,al=D.keep||s<DSQ_L-45?1:Math.max(0,(DSQ_L-s)/45),col=A.col;
  // the ngen's darkness and its light rising from the ground
  if(D.v){const p=SSd(t/50)*(s>DSQ_L-60?Math.max(0,(DSQ_L-s)/60):1);
    c.fillStyle='rgba(0,0,12,'+(.42*p).toFixed(2)+')';c.fillRect(0,0,LW,LH);
    const pul=.6+.4*Math.sin(frame/9),gx=(e._cx||72),gy=A.gy;
    const g=c.createRadialGradient(gx,gy,4,gx,gy,LW*.7);g.addColorStop(0,'rgba('+col+','+(.30*p*pul).toFixed(2)+')');g.addColorStop(1,'rgba('+col+',0)');
    c.save();c.globalCompositeOperation='lighter';c.fillStyle=g;c.fillRect(0,0,LW,LH);
    if(s<0)for(let k=0;k<10;k++){const ph=((frame*1.3+k*37)%90)/90;c.globalAlpha=(1-ph)*p*.8;c.fillStyle='rgba('+col+',1)';c.fillRect(Math.round(gx-A.W*.6+((k*53)%100)/100*A.W*1.2),Math.round(gy-ph*A.H*1.1),1.5,1.5)}
    c.restore();c.globalAlpha=1}
  c.imageSmoothingEnabled=false;
  if(s<0){   // the wekufü trembles while the ngen wakes
    const j=t%4<2?1:-1;c.save();c.scale(-1,1);c.drawImage(A.cvs,-(A.left+A.W)+j,A.top);c.restore();
    if(e.t==='ngamlef'&&typeof ngamThread==='function')ngamThread(c,e._cx,A.top,A.cvs);
    return}
  const k=s<34?0:s<68?1:s<104?2:3,F=dsqFrame(A,k);
  // the column of light that comes down on it
  if(D.v&&s<26){const q=s/26,gx=(e._cx||72);c.save();c.globalCompositeOperation='lighter';const w=A.W*(.35+.4*q);
    const g=c.createLinearGradient(gx-w,0,gx+w,0);g.addColorStop(0,'rgba('+col+',0)');g.addColorStop(.5,'rgba(255,255,255,'+(.85*(1-q)).toFixed(2)+')');g.addColorStop(1,'rgba('+col+',0)');
    c.fillStyle=g;c.fillRect(gx-w,0,w*2,A.gy);c.restore()}
  // Ngamleftripael hangs on its strand until it snaps at the third frame, then drops to the floor
  if(e.t==='ngamlef'){if(k<2&&typeof ngamThread==='function')ngamThread(c,e._cx,A.top,A.cvs);
    else if(s<84){const q=(s-68)/16,ax=e._cx||72;c.strokeStyle='rgba(60,58,64,'+(1-q).toFixed(2)+')';c.lineWidth=2;c.beginPath();c.moveTo(ax,0);c.lineTo(ax+Math.sin(s)*2,Math.max(2,A.top*(1-q)));c.stroke();c.lineWidth=1}}
  const sc=ng,fw=Math.round(F.im.width*sc),fh=Math.round(F.im.height*sc);
  let fx=A.left+Math.round(F.dx*sc),fy=A.top+Math.round(F.dy*sc);
  if(k===3&&(e.t==='ngamlef'||ET[e.t].fly&&e.t!=='fillantu'))fy=A.gy-2-fh;   // what is left lies on the floor
  if(k===2&&e.t==='ngamlef')fy+=Math.round(A.fallY);
  const sh=(s%34<8&&(D.yld?k<1:k<3))?(s%2?2:-2):0;
  c.globalAlpha=al;c.drawImage(F.im,fx+sh,fy,fw,fh);
  const since=s-[0,34,68,104][k];
  if(since<6&&!(D.yld&&k>0)){c.save();c.globalCompositeOperation='lighter';c.globalAlpha=(1-since/6)*.8*al;c.drawImage(F.im,fx+sh,fy,fw,fh);c.restore()}
  c.globalAlpha=1;
  drawFX(c,A,al)}
function stepSeq(A){const e=A.e,s=A.t-A.P,cx=e._cx||72,cy=A.top+A.H*.5,col=A.col.split(',').map(Number),hex='rgb('+col.join(',')+')';
  if(A.D.v&&A.t===1){ngenWake();B.shake=4}
  if(A.D.v&&A.t<A.P&&A.t%12===0)B.shake=Math.max(B.shake||0,3);
  if(A.D.v&&A.t===A.P-1&&!A.asked){A.asked=1;const nm=DSQ_NGN[A.D.v]||'El ngen';
    say([N('La tierra tiembla bajo tus pies: ¡'+nm+' despierta! Su newen sube desde el mapu y cae como luz sobre el wekufü.','The ground trembles under your feet: '+nm+' awakens! Its newen rises from the land and falls like light upon the wekufü.')],()=>{A.go=1;const d=document.getElementById('dlg');if(d)d.style.display='none'})}
  if(A.D.yld){const sea=e.t==='llufu5';   // no cracks, no sparks: the blow lands, he lowers his guard, a sign of respect, a calm last pose
    if(s===0){B.flash=6;B.shake=6;sfx('hit')}
    if(s===34){tone('triangle',392,392,.5,.08);if(sea)noiseBurst(.5,.12,500)}
    if(s===68){sfx('heal');if(sea){noiseBurst(.9,.22,300);tone('sine',180,90,.8,.12)}}
    if(s===104&&sea){noiseBurst(1.2,.2,250);tone('sine',140,70,1.1,.12)}
    if(A.t>=A.T&&!A.done){A.done=1;e.dead=true;e.fadeT=0;victory()}
    return}
  if(s===0){B.flash=12;B.shake=14;dThud(1);dCrack(1);if(A.D.v)sfx('beam');dSparks(A,cx,cy,26,A.D.v?hex:null,3)}
  if(s===34){B.shake=7;dCrack(1);dCrack(.7);dSparks(A,cx,cy,14,A.D.v?hex:null,2)}
  if(s===68){B.shake=18;B.flash=8;dRumble(.6,.3);noiseBurst(.25,.25,2000);dSparks(A,cx,cy,40,A.D.v?hex:'#fff2c8',4);dDust(A,cx,A.gy,10,1.2);
    if(e.t==='ngamlef'){A.fallV=0;noiseBurst(.12,.2,3000)}}
  if(s>68&&s<104&&e.t==='ngamlef'&&A.fallY<A.gy-2-(A.top+A.H)){A.fallV+=.35;A.fallY+=A.fallV;if(A.fallY>=A.gy-2-(A.top+A.H)){A.fallY=A.gy-2-(A.top+A.H);dThud(1);B.shake=14;dDust(A,cx,A.gy,12,1.5)}}
  if(s===104){dThud(.7);dDust(A,cx,A.gy,8,.8)}
  if(s>104&&s<170&&s%9===0)dSmoke(A,cx+(Math.random()-.5)*A.W*.4,A.gy-8,!A.D.v,1);
  if(s===DSQ_L-50&&A.D.v)sfx('heal');
  if(A.t>=A.T&&!A.done){A.done=1;e.dead=true;e.fadeT=0;victory()}}
